#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto doOp = [&](int x, int y){
        assert(x>0 && y>0 && x+y<n);
        ops.push_back({x,y});
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
    };

    for(int t=0;t<n-2;t++){
        int pos=-1;
        for(int i=t;i<n;i++) if(p[i]==t+1){pos=i;break;}
        if(pos==t) continue;

        int remaining = n - t; // elements from index t onwards that are unsorted
        // We work on the subarray [t..n-1] but operations are global.

        // Step 1: bring element to position (n-1) using prefix move
        if(pos < n-1){
            int x = pos+1, y = 1;
            if(x+y<n){
                doOp(x,y);
                pos = n-1; // element was last of prefix, now at end
            } else {
                // pos+1+1 >= n means pos >= n-2
                // pos == n-2: use x=1, y=2 -> suffix=[p[n-2],p[n-1]], prefix=[p[0]]
                // p[n-2] goes to pos 0, our element
                doOp(1,2);
                pos=0;
            }
        }
        // Now find element again to be safe
        for(int i=t;i<n;i++) if(p[i]==t+1){pos=i;break;}
        if(pos==t) continue;

        // Step 2: bring element from pos to position t
        // Use y = n-pos to grab it in suffix. It goes to position 0.
        // Use x = t if t > 0. Need t + (n-pos) < n => t < pos. Since pos >= t+1 (not at t), this holds if pos > t, which is true.
        if(t>0 && t+(n-pos)<n){
            doOp(t, n-pos);
        } else if(t==0){
            // element at pos, need at position 0. y=n-pos puts it at front. x=1,y=n-pos, need 1+n-pos<n => pos>1
            if(pos>1){ doOp(1, n-pos); pos=0; for(int i=0;i<n;i++) if(p[i]==1){pos=i;break;} if(pos!=0) doOp(1,n-1-1>0?1:1);}
            else { doOp(1,1); for(int i=0;i<n;i++) if(p[i]==1){pos=i;break;} if(pos!=0) continue; }
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
